//! Golden-table tests (BLD-24, BLD-25). The tables themselves are in `golden_tables.rs`,
//! GENERATED by `cargo run -p blindside-harness -- golden` and checked in as raw bits;
//! this file is the hand-written interpreter and the assertions.
//!
//! What the tables catch: a change to the RNG mix, to the `fixed` crate's arithmetic (an
//! upgrade, a feature), to the toolchain's codegen, or a platform where any of those
//! differ by a bit -- the R4 risk, before it shows up as a replay that verifies on one
//! machine and not another. CI runs these on Linux, macOS and Windows.

use crate::{DeterministicRng, Fx, Tick};

/// An `Fx` binary operation, as the arithmetic table names it. Wrapping forms so the
/// table can pin wrap-around too; the plain operators are the same bits when nothing
/// overflows, and panic when it does (see `fx_multiply_overflow_panics_in_every_profile`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FxOp {
    Add,
    Sub,
    Mul,
    Div,
}

pub fn apply(op: FxOp, a: Fx, b: Fx) -> Fx {
    match op {
        FxOp::Add => a.wrapping_add(b),
        FxOp::Sub => a.wrapping_sub(b),
        FxOp::Mul => a.wrapping_mul(b),
        FxOp::Div => a.wrapping_div(b),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::golden_tables::{FX_ARITHMETIC, RNG_DRAWS};

    #[test]
    fn rng_golden_table_matches() {
        assert!(RNG_DRAWS.len() >= 32, "BLD-24 wants at least 32 rows");
        for &(seed, tick, entity, purpose, want) in RNG_DRAWS {
            let got = DeterministicRng::new(seed)
                .draw(Tick(tick), entity, purpose)
                .to_bits() as u64;
            assert_eq!(
                got, want,
                "draw(seed {seed:#x}, tick {tick}, entity {entity}, {purpose:?}) = {got:#018x}, table says {want:#018x}"
            );
        }
    }

    #[test]
    fn fx_arithmetic_golden_table_matches() {
        assert!(!FX_ARITHMETIC.is_empty());
        for &(op, a, b, want) in FX_ARITHMETIC {
            let got = apply(op, Fx::from_bits(a as i64), Fx::from_bits(b as i64)).to_bits() as u64;
            assert_eq!(
                got, want,
                "{op:?}({a:#018x}, {b:#018x}) = {got:#018x}, table says {want:#018x}"
            );
        }
    }

    /// BLD-24: the chosen overflow behaviour, demonstrated. `Fx::MAX * 2` panics under
    /// `cargo test` and, because the workspace release profile sets `debug-assertions`
    /// (the switch `fixed` actually consults) as well as `overflow-checks`, under
    /// `cargo test --release` too. If this test ever passes in one profile and fails in
    /// the other, the profile is the desync.
    #[test]
    #[should_panic(expected = "overflow")]
    fn fx_multiply_overflow_panics_in_every_profile() {
        let a = std::hint::black_box(Fx::MAX);
        let b = std::hint::black_box(Fx::from_num(2));
        let c = a * b;
        std::hint::black_box(c);
    }

    /// The same overflow through the wrapping form is the pinned, silent wrap: that is
    /// what the world's position update uses on purpose.
    #[test]
    fn fx_wrapping_multiply_wraps() {
        let c = Fx::MAX.wrapping_mul(Fx::from_num(2));
        assert_eq!(c, Fx::from_bits(-2));
    }
}
